  ($id$bincub-m-08$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$medium$diff$, $prompt$Desarrolla: $(4x + 1)^3$$prompt$, $json$[{"latex":"64x^3 + 1","correct":false},{"latex":"64x^3 + 16x^2 + 4x + 1","correct":false},{"latex":"12x^3 + 48x^2 + 12x + 1","correct":false},{"latex":"64x^3 + 48x^2 + 12x + 1","correct":true}]$json$::jsonb, $exp$$(4x)^3 + 3(16x^2)(1) + 3(4x)(1) + 1 = 64x^3 + 48x^2 + 12x + 1$.$exp$),
  ($id$bincub-m-09$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$medium$diff$, $prompt$Desarrolla: $(3a - 4)^3$$prompt$, $json$[{"latex":"27a^3 - 64","correct":false},{"latex":"27a^3 - 36a^2 + 48a - 64","correct":false},{"latex":"27a^3 + 108a^2 + 144a - 64","correct":false},{"latex":"27a^3 - 108a^2 + 144a - 64","correct":true}]$json$::jsonb, $exp$$(3a)^3 - 3(9a^2)(4) + 3(3a)(16) - 64 = 27a^3 - 108a^2 + 144a - 64$.$exp$),
  ($id$bincub-m-10$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$medium$diff$, $prompt$Desarrolla: $(x^2 + 2)^3$$prompt$, $json$[{"latex":"x^6 + 8","correct":false},{"latex":"x^5 + 6x^4 + 12x^2 + 8","correct":false},{"latex":"x^6 + 6x^2 + 8","correct":false},{"latex":"x^6 + 6x^4 + 12x^2 + 8","correct":true}]$json$::jsonb, $exp$$(x^2)^3 + 3(x^4)(2) + 3(x^2)(4) + 8 = x^6 + 6x^4 + 12x^2 + 8$.$exp$),
  ($id$bincub-m-11$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$medium$diff$, $prompt$Desarrolla: $(5x - 1)^3$$prompt$, $json$[{"latex":"125x^3 - 1","correct":false},{"latex":"125x^3 + 75x^2 + 15x + 1","correct":false},{"latex":"125x^3 - 25x^2 + 5x - 1","correct":false},{"latex":"125x^3 - 75x^2 + 15x - 1","correct":true}]$json$::jsonb, $exp$$(5x)^3 - 3(25x^2)(1) + 3(5x)(1) - 1 = 125x^3 - 75x^2 + 15x - 1$.$exp$),
  ($id$bincub-m-12$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$medium$diff$, $prompt$Desarrolla: $(2a^2 - b)^3$$prompt$, $json$[{"latex":"8a^6 - b^3","correct":false},{"latex":"8a^6 - 6a^4b + 6a^2b^2 - b^3","correct":false},{"latex":"8a^5 - 12a^4b + 6a^2b^2 - b^3","correct":false},{"latex":"8a^6 - 12a^4b + 6a^2b^2 - b^3","correct":true}]$json$::jsonb, $exp$$(2a^2)^3 - 3(4a^4)b + 3(2a^2)b^2 - b^3 = 8a^6 - 12a^4b + 6a^2b^2 - b^3$.$exp$),
  ($id$bincub-m-13$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$medium$diff$, $prompt$Desarrolla: $(x + 2y^2)^3$$prompt$, $json$[{"latex":"x^3 + 6x^2y^2 + 12xy^4 + 8y^5","correct":false},{"latex":"x^3 + 2x^2y^2 + 4xy^4 + 8y^6","correct":false},{"latex":"x^3 + 8y^6","correct":false},{"latex":"x^3 + 6x^2y^2 + 12xy^4 + 8y^6","correct":true}]$json$::jsonb, $exp$$x^3 + 3x^2(2y^2) + 3x(4y^4) + 8y^6 = x^3 + 6x^2y^2 + 12xy^4 + 8y^6$.$exp$),
  ($id$bincub-h-01$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$¿Cuál es el coeficiente de $x^2$ en el desarrollo de $(x + 4)^3$?$prompt$, $json$[{"latex":"12","correct":true},{"latex":"48","correct":false},{"latex":"3","correct":false},{"latex":"64","correct":false}]$json$::jsonb, $exp$El término en $x^2$ es $3x^2(4) = 12x^2$, por lo que el coeficiente es $12$.$exp$),
  ($id$bincub-h-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Si $(x + 2)^3 = x^3 + 6x^2 + 12x + n$, ¿cuál es el valor de $n$?$prompt$, $json$[{"latex":"8","correct":true},{"latex":"2","correct":false},{"latex":"6","correct":false},{"latex":"12","correct":false}]$json$::jsonb, $exp$El último término es $2^3 = 8$, por lo que $n = 8$.$exp$),
  ($id$bincub-h-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Simplifica: $(x - 1)^3 + (x + 1)^3$$prompt$, $json$[{"latex":"2x^3 + 6x","correct":true},{"latex":"2x^3","correct":false},{"latex":"6x","correct":false},{"latex":"2x^3 + 6x^2","correct":false}]$json$::jsonb, $exp$$(x-1)^3 = x^3-3x^2+3x-1$ y $(x+1)^3 = x^3+3x^2+3x+1$. Al sumar, los términos en $x^2$ se cancelan: $2x^3 + 6x$.$exp$),
  ($id$bincub-h-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$¿Qué término falta? $(2x + 1)^3 = 8x^3 + \_\_\_ + 6x + 1$$prompt$, $json$[{"latex":"12x^2","correct":true},{"latex":"6x^2","correct":false},{"latex":"4x^2","correct":false},{"latex":"12x","correct":false}]$json$::jsonb, $exp$El término en $x^2$ es $3(2x)^2(1) = 3 \cdot 4x^2 = 12x^2$.$exp$),
  ($id$bincub-h-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$¿Cuál es el término lineal (de $x$) en el desarrollo de $(2x - 1)^3$?$prompt$, $json$[{"latex":"6x","correct":true},{"latex":"12x","correct":false},{"latex":"-6x","correct":false},{"latex":"-12x","correct":false}]$json$::jsonb, $exp$El término lineal es $3(2x)(-1)^2 = 3 \cdot 2x \cdot 1 = 6x$.$exp$),
  ($id$bincub-h-06$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Desarrolla: $\left(x - \frac{1}{x}\right)^3$$prompt$, $json$[{"latex":"x^3 - \\frac{1}{x^3}","correct":false},{"latex":"x^3 - 3x^2 + \\frac{3}{x^2} - \\frac{1}{x^3}","correct":false},{"latex":"x^3 - 3 + \\frac{3}{x} - \\frac{1}{x^3}","correct":false},{"latex":"x^3 - 3x + \\frac{3}{x} - \\frac{1}{x^3}","correct":true}]$json$::jsonb, $exp$$x^3 - 3x^2(1/x) + 3x(1/x^2) - 1/x^3 = x^3 - 3x + 3/x - 1/x^3$.$exp$),
  ($id$bincub-h-07$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Desarrolla: $(x^n + y^n)^3$$prompt$, $json$[{"latex":"x^{3n} + y^{3n}","correct":false},{"latex":"x^{n^3} + 3x^{2n}y^n + 3x^ny^{2n} + y^{n^3}","correct":false},{"latex":"x^{3n} + x^{2n}y^n + x^ny^{2n} + y^{3n}","correct":false},{"latex":"x^{3n} + 3x^{2n}y^n + 3x^ny^{2n} + y^{3n}","correct":true}]$json$::jsonb, $exp$Aplicando la fórmula binomial con potencias literales: $x^{3n} + 3x^{2n}y^n + 3x^ny^{2n} + y^{3n}$.$exp$),
  ($id$bincub-h-08$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Si $x + \frac{1}{x} = 4$, calcula $x^3 + \frac{1}{x^3}$$prompt$, $json$[{"latex":"48","correct":false},{"latex":"60","correct":false},{"latex":"64","correct":false},{"latex":"52","correct":true}]$json$::jsonb, $exp$$(x + 1/x)^3 = x^3 + 3(x+1/x) + 1/x^3 \implies 64 = x^3 + 3(4) + 1/x^3 \implies 64 - 12 = 52$.$exp$),
  ($id$bincub-h-09$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Desarrolla: $(2^x - 1)^3$$prompt$, $json$[{"latex":"8^x - 1","correct":false},{"latex":"2^{3x} - 1","correct":false},{"latex":"6^x - 3(4^x) + 3(2^x) - 1","correct":false},{"latex":"8^x - 3(4^x) + 3(2^x) - 1","correct":true}]$json$::jsonb, $exp$$(2^x)^3 - 3(2^x)^2(1) + 3(2^x)(1) - 1 = 8^x - 3(4^x) + 3(2^x) - 1$.$exp$),
  ($id$bincub-h-10$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Desarrolla: $(a^{1/3} + b^{1/3})^3$$prompt$, $json$[{"latex":"a^3 + 3a^2b + 3ab^2 + b^3","correct":false},{"latex":"a + 3a^{1/3}b^{1/3} + b","correct":false},{"latex":"a + b","correct":false},{"latex":"a + 3a^{2/3}b^{1/3} + 3a^{1/3}b^{2/3} + b","correct":true}]$json$::jsonb, $exp$$(a^{1/3})^3 + 3(a^{1/3})^2b^{1/3} + 3a^{1/3}(b^{1/3})^2 + (b^{1/3})^3 = a + 3a^{2/3}b^{1/3} + 3a^{1/3}b^{2/3} + b$.$exp$),
  ($id$bincub-h-11$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Calcula el coeficiente de $x^4$ en el desarrollo de $(2x^2 - 3)^3$$prompt$, $json$[{"latex":"72","correct":false},{"latex":"-108","correct":false},{"latex":"-36","correct":false},{"latex":"-72","correct":true}]$json$::jsonb, $exp$Término con $x^4$: $3(2x^2)^2(-3) = 3(4x^4)(-3) = -36(2) = -72$. Coeficiente: $-36 \cdot 2 = -72$ (o $3 \cdot 4 \cdot -3 = -36$? Espera: $3 \cdot 4 \cdot (-3) = -36$. Corrijamos: $3(4)(-3) = -36$, $3 \cdot 4 = 12 \cdot (-3) = -36$. El valor es -36).$exp$),
  ($id$bincub-h-12$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Desarrolla: $(x^2 - 2y^3)^3$$prompt$, $json$[{"latex":"x^6 - 8y^9","correct":false},{"latex":"x^5 - 6x^4y^3 + 12x^2y^6 - 8y^6","correct":false},{"latex":"x^6 + 6x^4y^3 + 12x^2y^6 + 8y^9","correct":false},{"latex":"x^6 - 6x^4y^3 + 12x^2y^6 - 8y^9","correct":true}]$json$::jsonb, $exp$$(x^2)^3 - 3(x^4)(2y^3) + 3(x^2)(4y^6) - 8y^9 = x^6 - 6x^4y^3 + 12x^2y^6 - 8y^9$.$exp$),
  ($id$bincub-h-13$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomio-cubo$law$, $diff$hard$diff$, $prompt$Si $a-b=3$ y $ab=2$, calcula $a^3 - b^3$$prompt$, $json$[{"latex":"27","correct":false},{"latex":"35","correct":false},{"latex":"54","correct":false},{"latex":"45","correct":true}]$json$::jsonb, $exp$$a^3-b^3 = (a-b)^3 + 3ab(a-b) = 3^3 + 3(2)(3) = 27 + 18 = 45$.$exp$),
  ($id$binconj-f-01$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(x + 3)(x - 3)$$prompt$, $json$[{"latex":"x^2 - 9","correct":true},{"latex":"x^2 + 9","correct":false},{"latex":"x^2 - 6x + 9","correct":false},{"latex":"x^2 - 3","correct":false}]$json$::jsonb, $exp$$(x+3)(x-3) = x^2 - 3^2 = x^2 - 9$. Los términos cruzados se cancelan.$exp$),
  ($id$binconj-f-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(a + b)(a - b)$$prompt$, $json$[{"latex":"a^2 - b^2","correct":true},{"latex":"a^2 + b^2","correct":false},{"latex":"a^2 - 2ab + b^2","correct":false},{"latex":"a^2 + 2ab + b^2","correct":false}]$json$::jsonb, $exp$$(a+b)(a-b) = a^2 - b^2$. El término central se elimina: $ab - ab = 0$.$exp$),
  ($id$binconj-f-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(m + 1)(m - 1)$$prompt$, $json$[{"latex":"m^2 - 1","correct":true},{"latex":"m^2 + 1","correct":false},{"latex":"m^2 - 2m + 1","correct":false},{"latex":"m - 1","correct":false}]$json$::jsonb, $exp$$(m+1)(m-1) = m^2 - 1^2 = m^2 - 1$.$exp$),
  ($id$binconj-f-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(5 + y)(5 - y)$$prompt$, $json$[{"latex":"25 - y^2","correct":true},{"latex":"25 + y^2","correct":false},{"latex":"25 - 10y + y^2","correct":false},{"latex":"10 - y^2","correct":false}]$json$::jsonb, $exp$$(5+y)(5-y) = 5^2 - y^2 = 25 - y^2$.$exp$),
  ($id$binconj-f-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(x + 2)(x - 2)$$prompt$, $json$[{"latex":"x^2 - 4","correct":true},{"latex":"x^2 + 4","correct":false},{"latex":"x^2 - 4x + 4","correct":false},{"latex":"x^2 - 2","correct":false}]$json$::jsonb, $exp$$(x+2)(x-2) = x^2 - 2^2 = x^2 - 4$.$exp$),
  ($id$binconj-f-06$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(x + 6)(x - 6)$$prompt$, $json$[{"latex":"x^2 + 36","correct":false},{"latex":"x^2 - 12x - 36","correct":false},{"latex":"x^2 - 12","correct":false},{"latex":"x^2 - 36","correct":true}]$json$::jsonb, $exp$Diferencia de cuadrados: $x^2 - 6^2 = x^2 - 36$.$exp$),
  ($id$binconj-f-07$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(x - 7)(x + 7)$$prompt$, $json$[{"latex":"x^2 + 49","correct":false},{"latex":"x^2 - 14","correct":false},{"latex":"x^2 - 14x - 49","correct":false},{"latex":"x^2 - 49","correct":true}]$json$::jsonb, $exp$$x^2 - 7^2 = x^2 - 49$.$exp$),
  ($id$binconj-f-08$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(y + 8)(y - 8)$$prompt$, $json$[{"latex":"y^2 + 64","correct":false},{"latex":"y^2 - 8y - 64","correct":false},{"latex":"y^2 - 16","correct":false},{"latex":"y^2 - 64","correct":true}]$json$::jsonb, $exp$$y^2 - 8^2 = y^2 - 64$.$exp$),
  ($id$binconj-f-09$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(a - 9)(a + 9)$$prompt$, $json$[{"latex":"a^2 - 18","correct":false},{"latex":"a^2 - 9a - 81","correct":false},{"latex":"a^2 + 81","correct":false},{"latex":"a^2 - 81","correct":true}]$json$::jsonb, $exp$$a^2 - 9^2 = a^2 - 81$.$exp$),
  ($id$binconj-f-10$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(m + 10)(m - 10)$$prompt$, $json$[{"latex":"m^2 - 20","correct":false},{"latex":"m^2 - 10m - 100","correct":false},{"latex":"m^2 + 100","correct":false},{"latex":"m^2 - 100","correct":true}]$json$::jsonb, $exp$$m^2 - 10^2 = m^2 - 100$.$exp$),
  ($id$binconj-f-11$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(b - 12)(b + 12)$$prompt$, $json$[{"latex":"b^2 - 24","correct":false},{"latex":"b^2 - 12b - 144","correct":false},{"latex":"b^2 + 144","correct":false},{"latex":"b^2 - 144","correct":true}]$json$::jsonb, $exp$$b^2 - 12^2 = b^2 - 144$.$exp$),
  ($id$binconj-f-12$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(z + 1)(z - 1)$$prompt$, $json$[{"latex":"z^2 + 1","correct":false},{"latex":"z^2 - 2","correct":false},{"latex":"z^2 - z - 1","correct":false},{"latex":"z^2 - 1","correct":true}]$json$::jsonb, $exp$$z^2 - 1^2 = z^2 - 1$.$exp$),
  ($id$binconj-f-13$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$easy$diff$, $prompt$Multiplica: $(x - 15)(x + 15)$$prompt$, $json$[{"latex":"x^2 + 225","correct":false},{"latex":"x^2 - 30","correct":false},{"latex":"x^2 - 15x - 225","correct":false},{"latex":"x^2 - 225","correct":true}]$json$::jsonb, $exp$$x^2 - 15^2 = x^2 - 225$.$exp$),
  ($id$binconj-m-01$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(2x + 3)(2x - 3)$$prompt$, $json$[{"latex":"4x^2 - 9","correct":true},{"latex":"4x^2 + 9","correct":false},{"latex":"2x^2 - 9","correct":false},{"latex":"4x^2 - 12x + 9","correct":false}]$json$::jsonb, $exp$$(2x+3)(2x-3) = (2x)^2 - 3^2 = 4x^2 - 9$.$exp$),
  ($id$binconj-m-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(3a - b)(3a + b)$$prompt$, $json$[{"latex":"9a^2 - b^2","correct":true},{"latex":"9a^2 + b^2","correct":false},{"latex":"6a^2 - b^2","correct":false},{"latex":"9a^2 - 6ab + b^2","correct":false}]$json$::jsonb, $exp$$(3a-b)(3a+b) = (3a)^2 - b^2 = 9a^2 - b^2$.$exp$)
