  ($id$binconj-m-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(x - 7)(x + 7)$$prompt$, $json$[{"latex":"x^2 - 49","correct":true},{"latex":"x^2 + 49","correct":false},{"latex":"x^2 - 14x + 49","correct":false},{"latex":"x^2 - 7","correct":false}]$json$::jsonb, $exp$$(x-7)(x+7) = x^2 - 7^2 = x^2 - 49$.$exp$),
  ($id$binconj-m-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(\frac{1}{2} + x)(\frac{1}{2} - x)$$prompt$, $json$[{"latex":"\\frac{1}{4} - x^2","correct":true},{"latex":"\\frac{1}{4} + x^2","correct":false},{"latex":"\\frac{1}{2} - x^2","correct":false},{"latex":"\\frac{1}{4} - x","correct":false}]$json$::jsonb, $exp$$(\frac12+x)(\frac12-x) = (\frac12)^2 - x^2 = \frac14 - x^2$.$exp$),
  ($id$binconj-m-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(5x + 2y)(5x - 2y)$$prompt$, $json$[{"latex":"25x^2 - 4y^2","correct":true},{"latex":"25x^2 + 4y^2","correct":false},{"latex":"5x^2 - 2y^2","correct":false},{"latex":"25x^2 - 10xy + 4y^2","correct":false}]$json$::jsonb, $exp$$(5x+2y)(5x-2y) = (5x)^2 - (2y)^2 = 25x^2 - 4y^2$.$exp$),
  ($id$binconj-m-06$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(4x + 3)(4x - 3)$$prompt$, $json$[{"latex":"16x^2 + 9","correct":false},{"latex":"16x^2 - 24x - 9","correct":false},{"latex":"4x^2 - 9","correct":false},{"latex":"16x^2 - 9","correct":true}]$json$::jsonb, $exp$$(4x)^2 - 3^2 = 16x^2 - 9$.$exp$),
  ($id$binconj-m-07$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$binomios-conjugados$law$, $diff$medium$diff$, $prompt$Multiplica: $(5a - 2b)(5a + 2b)$$prompt$, $json$[{"latex":"10a^2 - 4b^2","correct":false},{"latex":"25a^2 - 20ab - 4b^2","correct":false},{"latex":"25a^2 + 4b^2","correct":false},{"latex":"25a^2 - 4b^2","correct":true}]$json$::jsonb, $exp$$(5a)^2 - (2b)^2 = 25a^2 - 4b^2$.$exp$),
