  ($id$sumcub-m-07$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $8a^3 + 27b^3$$prompt$, $json$[{"latex":"(2a + 3b)^3","correct":false},{"latex":"(2a - 3b)(4a^2 + 6ab + 9b^2)","correct":false},{"latex":"(2a + 3b)(4a^2 + 6ab + 9b^2)","correct":false},{"latex":"(2a + 3b)(4a^2 - 6ab + 9b^2)","correct":true}]$json$::jsonb, $exp$$a=2a$, $b=3b$: $(2a+3b)(4a^2-6ab+9b^2)$.$exp$),
  ($id$sumcub-m-08$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $64x^3 + 1$$prompt$, $json$[{"latex":"(4x + 1)^3","correct":false},{"latex":"(4x - 1)(16x^2 + 4x + 1)","correct":false},{"latex":"(4x + 1)(16x^2 + 4x + 1)","correct":false},{"latex":"(4x + 1)(16x^2 - 4x + 1)","correct":true}]$json$::jsonb, $exp$$\sqrt[3]{64x^3}=4x$: $(4x+1)(16x^2-4x+1)$.$exp$),
  ($id$sumcub-m-09$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $125u^3 + 8v^3$$prompt$, $json$[{"latex":"(5u + 2v)(25u^2 + 10uv + 4v^2)","correct":false},{"latex":"(5u - 2v)(25u^2 + 10uv + 4v^2)","correct":false},{"latex":"(5u + 2v)^3","correct":false},{"latex":"(5u + 2v)(25u^2 - 10uv + 4v^2)","correct":true}]$json$::jsonb, $exp$$\sqrt[3]{125u^3}=5u$, $\sqrt[3]{8v^3}=2v$: $(5u+2v)(25u^2-10uv+4v^2)$.$exp$),
  ($id$sumcub-m-10$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $x^6 + 27$$prompt$, $json$[{"latex":"(x^2 + 3)(x^4 + 3x^2 + 9)","correct":false},{"latex":"(x^2 + 3)^3","correct":false},{"latex":"(x^3 + 3)(x^3 - 9)","correct":false},{"latex":"(x^2 + 3)(x^4 - 3x^2 + 9)","correct":true}]$json$::jsonb, $exp$$\sqrt[3]{x^6}=x^2$, $\sqrt[3]{27}=3$: $(x^2+3)(x^4-3x^2+9)$.$exp$),
  ($id$sumcub-m-11$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $27m^3 + 64n^3$$prompt$, $json$[{"latex":"(3m + 4n)(9m^2 + 12mn + 16n^2)","correct":false},{"latex":"(3m - 4n)(9m^2 + 12mn + 16n^2)","correct":false},{"latex":"(3m + 4n)^3","correct":false},{"latex":"(3m + 4n)(9m^2 - 12mn + 16n^2)","correct":true}]$json$::jsonb, $exp$$3m$ y $4n$: $(3m+4n)(9m^2-12mn+16n^2)$.$exp$),
  ($id$sumcub-m-12$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $8x^3 + 125$$prompt$, $json$[{"latex":"(2x + 5)^3","correct":false},{"latex":"(2x - 5)(4x^2 + 10x + 25)","correct":false},{"latex":"(2x + 5)(4x^2 + 10x + 25)","correct":false},{"latex":"(2x + 5)(4x^2 - 10x + 25)","correct":true}]$json$::jsonb, $exp$$\sqrt[3]{8x^3}=2x$, $\sqrt[3]{125}=5$: $(2x+5)(4x^2-10x+25)$.$exp$),
  ($id$sumcub-m-13$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$medium$diff$, $prompt$Factoriza: $x^3y^3 + 8$$prompt$, $json$[{"latex":"(xy + 2)(x^2y^2 + 2xy + 4)","correct":false},{"latex":"(xy + 2)^3","correct":false},{"latex":"(xy - 2)(x^2y^2 + 2xy + 4)","correct":false},{"latex":"(xy + 2)(x^2y^2 - 2xy + 4)","correct":true}]$json$::jsonb, $exp$$\sqrt[3]{x^3y^3}=xy$: $(xy+2)(x^2y^2-2xy+4)$.$exp$),
  ($id$sumcub-h-01$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $x^6 + 1$$prompt$, $json$[{"latex":"(x^2 + 1)(x^4 - x^2 + 1)","correct":true},{"latex":"(x^2 + 1)^3","correct":false},{"latex":"(x^2 + 1)(x^4 + x^2 + 1)","correct":false},{"latex":"(x^2 + 1)(x^4 - 2x^2 + 1)","correct":false}]$json$::jsonb, $exp$$x^6 + 1 = (x^2)^3 + 1^3 = (x^2+1)(x^4 - x^2 + 1)$.$exp$),
  ($id$sumcub-h-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Si $x^3 + 27 = (x + 3)(x^2 + ax + 9)$, ¿cuál es el valor de $a$?$prompt$, $json$[{"latex":"-3","correct":true},{"latex":"3","correct":false},{"latex":"-6","correct":false},{"latex":"6","correct":false}]$json$::jsonb, $exp$En $x^3 + b^3 = (x+b)(x^2 - bx + b^2)$ con $b=3$, el término central es $-bx = -3x$, por lo que $a = -3$.$exp$),
  ($id$sumcub-h-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $64x^3 + 1$$prompt$, $json$[{"latex":"(4x + 1)(16x^2 - 4x + 1)","correct":true},{"latex":"(4x + 1)^3","correct":false},{"latex":"(4x + 1)(16x^2 + 4x + 1)","correct":false},{"latex":"(4x + 1)(16x^2 - 8x + 1)","correct":false}]$json$::jsonb, $exp$$64x^3 + 1 = (4x)^3 + 1^3 = (4x+1)(16x^2 - 4x + 1)$.$exp$),
  ($id$sumcub-h-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Simplifica: $\frac{x^3 + 8}{x + 2}$$prompt$, $json$[{"latex":"x^2 - 2x + 4","correct":true},{"latex":"x^2 + 2x + 4","correct":false},{"latex":"x + 4","correct":false},{"latex":"x^2 - 4","correct":false}]$json$::jsonb, $exp$$x^3 + 8 = (x+2)(x^2 - 2x + 4)$. Al dividir entre $x+2$ queda $x^2 - 2x + 4$.$exp$),
  ($id$sumcub-h-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $27x^3 + 8y^3$$prompt$, $json$[{"latex":"(3x + 2y)(9x^2 - 6xy + 4y^2)","correct":true},{"latex":"(3x + 2y)^3","correct":false},{"latex":"(3x + 2y)(9x^2 + 6xy + 4y^2)","correct":false},{"latex":"(3x + 2y)(9x^2 - 12xy + 4y^2)","correct":false}]$json$::jsonb, $exp$$27x^3 + 8y^3 = (3x)^3 + (2y)^3 = (3x+2y)(9x^2 - 6xy + 4y^2)$.$exp$),
  ($id$sumcub-h-06$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $x^{3n} + 8$$prompt$, $json$[{"latex":"(x^n + 2)(x^{2n} + 2x^n + 4)","correct":false},{"latex":"(x^n - 2)(x^{2n} + 2x^n + 4)","correct":false},{"latex":"(x^n + 2)^3","correct":false},{"latex":"(x^n + 2)(x^{2n} - 2x^n + 4)","correct":true}]$json$::jsonb, $exp$$\sqrt[3]{x^{3n}}=x^n$, $\sqrt[3]{8}=2$: $(x^n+2)(x^{2n}-2x^n+4)$.$exp$),
  ($id$sumcub-h-07$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $e^{3x} + 1$$prompt$, $json$[{"latex":"(e^x + 1)^3","correct":false},{"latex":"(e^x - 1)(e^{2x} + e^x + 1)","correct":false},{"latex":"(e^x + 1)(e^{2x} + e^x + 1)","correct":false},{"latex":"(e^x + 1)(e^{2x} - e^x + 1)","correct":true}]$json$::jsonb, $exp$Con $u=e^x$: $(e^x+1)((e^x)^2 - e^x(1) + 1) = (e^x+1)(e^{2x}-e^x+1)$.$exp$),
  ($id$sumcub-h-08$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $\frac{x^3}{8} + \frac{y^3}{27}$$prompt$, $json$[{"latex":"\\left(\\frac{x}{2} + \\frac{y}{3}\\right)^3","correct":false},{"latex":"\\left(\\frac{x}{2} - \\frac{y}{3}\\right)\\left(\\frac{x^2}{4} + \\frac{xy}{6} + \\frac{y^2}{9}\\right)","correct":false},{"latex":"\\left(\\frac{x}{2} + \\frac{y}{3}\\right)\\left(\\frac{x^2}{4} + \\frac{xy}{6} + \\frac{y^2}{9}\\right)","correct":false},{"latex":"\\left(\\frac{x}{2} + \\frac{y}{3}\\right)\\left(\\frac{x^2}{4} - \\frac{xy}{6} + \\frac{y^2}{9}\\right)","correct":true}]$json$::jsonb, $exp$Raíces cúbicas: $\frac{x}{2}$ y $\frac{y}{3}$.$exp$),
  ($id$sumcub-h-09$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Simplifica la fracción: $\frac{x^3 + 8}{x + 2}$$prompt$, $json$[{"latex":"x^2 + 2x + 4","correct":false},{"latex":"x^2 + 4","correct":false},{"latex":"(x+2)^2","correct":false},{"latex":"x^2 - 2x + 4","correct":true}]$json$::jsonb, $exp$Como $x^3+8 = (x+2)(x^2-2x+4)$, al dividir entre $(x+2)$ queda $x^2-2x+4$.$exp$),
  ($id$sumcub-h-10$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $8^x + 27$$prompt$, $json$[{"latex":"(2^x + 3)^3","correct":false},{"latex":"(2^x - 3)(4^x + 3(2^x) + 9)","correct":false},{"latex":"(2^x + 3)(4^x + 3(2^x) + 9)","correct":false},{"latex":"(2^x + 3)(4^x - 3(2^x) + 9)","correct":true}]$json$::jsonb, $exp$$8^x = (2^x)^3$: $(2^x+3)((2^x)^2 - 3(2^x) + 9) = (2^x+3)(4^x - 3(2^x) + 9)$.$exp$),
  ($id$sumcub-h-11$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $(x+1)^3 + 8$$prompt$, $json$[{"latex":"(x + 3)(x^2 + 7)","correct":false},{"latex":"(x + 3)((x+1)^2 - 2(x+1) + 4)","correct":false},{"latex":"(x + 3)(x^2 - 2x + 4)","correct":false},{"latex":"(x + 3)(x^2 - 2)","correct":true}]$json$::jsonb, $exp$$((x+1)+2)((x+1)^2 - 2(x+1) + 4) = (x+3)(x^2+2x+1 - 2x-2 + 4) = (x+3)(x^2+3)$ (o $((x+1)+2)((x+1)^2-2(x+1)+4)$).$exp$),
  ($id$sumcub-h-12$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Simplifica: $\frac{a^3+b^3}{a^2-ab+b^2}$$prompt$, $json$[{"latex":"a - b","correct":false},{"latex":"1","correct":false},{"latex":"(a+b)^2","correct":false},{"latex":"a + b","correct":true}]$json$::jsonb, $exp$Factorizando el numerador: $\frac{(a+b)(a^2-ab+b^2)}{a^2-ab+b^2} = a+b$.$exp$),
  ($id$sumcub-h-13$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$suma-cubos$law$, $diff$hard$diff$, $prompt$Factoriza: $a^9 + b^9$$prompt$, $json$[{"latex":"(a+b)(a^8 - a^7b + \\dots)","correct":false},{"latex":"(a^3 - b^3)(a^6 + a^3b^3 + b^6)","correct":false},{"latex":"(a^3 + b^3)^3","correct":false},{"latex":"(a^3 + b^3)(a^6 - a^3b^3 + b^6)","correct":true}]$json$::jsonb, $exp$Visto como $(a^3)^3 + (b^3)^3$: $(a^3+b^3)(a^6-a^3b^3+b^6)$.$exp$),
  ($id$tricp-f-01$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $x^2 + 6x + 9$$prompt$, $json$[{"latex":"(x + 3)^2","correct":true},{"latex":"(x + 3)(x - 3)","correct":false},{"latex":"(x + 9)^2","correct":false},{"latex":"(x + 3)(x + 6)","correct":false}]$json$::jsonb, $exp$$x^2 + 6x + 9 = (x+3)^2$ porque $2 \cdot 3 = 6$ y $3^2 = 9$.$exp$),
  ($id$tricp-f-02$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $x^2 - 2x + 1$$prompt$, $json$[{"latex":"(x - 1)^2","correct":true},{"latex":"(x + 1)^2","correct":false},{"latex":"(x - 1)(x + 1)","correct":false},{"latex":"(x - 2)^2","correct":false}]$json$::jsonb, $exp$$x^2 - 2x + 1 = (x-1)^2$ porque $-2x = -2(x)(1)$ y $1 = 1^2$.$exp$),
  ($id$tricp-f-03$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $a^2 + 2ab + b^2$$prompt$, $json$[{"latex":"(a + b)^2","correct":true},{"latex":"(a + b)(a - b)","correct":false},{"latex":"(a - b)^2","correct":false},{"latex":"a^2 + b^2","correct":false}]$json$::jsonb, $exp$$a^2 + 2ab + b^2 = (a+b)^2$. Es el cuadrado de un binomio.$exp$),
  ($id$tricp-f-04$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $x^2 + 10x + 25$$prompt$, $json$[{"latex":"(x + 5)^2","correct":true},{"latex":"(x + 5)(x - 5)","correct":false},{"latex":"(x + 10)^2","correct":false},{"latex":"(x + 5)(x + 2)","correct":false}]$json$::jsonb, $exp$$x^2 + 10x + 25 = (x+5)^2$ porque $2 \cdot 5 = 10$ y $5^2 = 25$.$exp$),
  ($id$tricp-f-05$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $y^2 - 4y + 4$$prompt$, $json$[{"latex":"(y - 2)^2","correct":true},{"latex":"(y + 2)^2","correct":false},{"latex":"(y - 2)(y + 2)","correct":false},{"latex":"(y - 4)^2","correct":false}]$json$::jsonb, $exp$$y^2 - 4y + 4 = (y-2)^2$ porque $2 \cdot 2 = 4$ y $2^2 = 4$.$exp$),
  ($id$tricp-f-06$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $x^2 + 14x + 49$$prompt$, $json$[{"latex":"(x - 7)^2","correct":false},{"latex":"(x + 14)^2","correct":false},{"latex":"(x + 7)(x - 7)","correct":false},{"latex":"(x + 7)^2","correct":true}]$json$::jsonb, $exp$Raíces: $\sqrt{x^2}=x$, $\sqrt{49}=7$, y $2(x)(7)=14x$. Resultado: $(x+7)^2$.$exp$),
  ($id$tricp-f-07$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $x^2 - 16x + 64$$prompt$, $json$[{"latex":"(x + 8)^2","correct":false},{"latex":"(x - 16)^2","correct":false},{"latex":"(x - 8)(x + 8)","correct":false},{"latex":"(x - 8)^2","correct":true}]$json$::jsonb, $exp$Doble producto negativo: $2(x)(8)=16x \implies (x-8)^2$.$exp$),
  ($id$tricp-f-08$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $y^2 + 18y + 81$$prompt$, $json$[{"latex":"(y - 9)^2","correct":false},{"latex":"(y + 9)(y - 9)","correct":false},{"latex":"(y + 18)^2","correct":false},{"latex":"(y + 9)^2","correct":true}]$json$::jsonb, $exp$Raíces: $y$ y $9$, doble producto $2(9)y=18y$.$exp$),
  ($id$tricp-f-09$id$, $sec$algebra$sec$, $sub$productos-notables$sub$, $law$trinomio-cuadrado-perfecto$law$, $diff$easy$diff$, $prompt$Factoriza: $a^2 - 20a + 100$$prompt$, $json$[{"latex":"(a - 20)^2","correct":false},{"latex":"(a - 10)(a + 10)","correct":false},{"latex":"(a + 10)^2","correct":false},{"latex":"(a - 10)^2","correct":true}]$json$::jsonb, $exp$Raíces: $a$ y $10$, signo medio negativo: $(a-10)^2$.$exp$)
